    /// <summary>Copies the default coefficient distributions of the quantizer range <paramref name="index"/>, 0 to 3 (init_coeff_cdfs).</summary>
    public static void InitializeCoefficients(Span<ushort> cdfs, int index)
    {
        Av1Tables.DefaultTxbSkipCdf.Slice(index * 195, 195).CopyTo(cdfs[TxbSkip..]);
        Av1Tables.DefaultEobPt16Cdf.Slice(index * 24, 24).CopyTo(cdfs[EobPt16..]);
        Av1Tables.DefaultEobPt32Cdf.Slice(index * 28, 28).CopyTo(cdfs[EobPt32..]);
        Av1Tables.DefaultEobPt64Cdf.Slice(index * 32, 32).CopyTo(cdfs[EobPt64..]);
        Av1Tables.DefaultEobPt128Cdf.Slice(index * 36, 36).CopyTo(cdfs[EobPt128..]);
        Av1Tables.DefaultEobPt256Cdf.Slice(index * 40, 40).CopyTo(cdfs[EobPt256..]);
        Av1Tables.DefaultEobPt512Cdf.Slice(index * 22, 22).CopyTo(cdfs[EobPt512..]);
        Av1Tables.DefaultEobPt1024Cdf.Slice(index * 24, 24).CopyTo(cdfs[EobPt1024..]);
        Av1Tables.DefaultEobExtraCdf.Slice(index * 270, 270).CopyTo(cdfs[EobExtra..]);
        Av1Tables.DefaultDcSignCdf.Slice(index * 18, 18).CopyTo(cdfs[DcSign..]);
        Av1Tables.DefaultCoeffBaseEobCdf.Slice(index * 160, 160).CopyTo(cdfs[CoeffBaseEob..]);
        Av1Tables.DefaultCoeffBaseCdf.Slice(index * 2100, 2100).CopyTo(cdfs[CoeffBase..]);
        Av1Tables.DefaultCoeffBrCdf.Slice(index * 1050, 1050).CopyTo(cdfs[CoeffBr..]);
    }

